// 1. Core API file (Loaded on boot)
export const api = createApi({
  reducerPath: 'api',
  baseQuery: fetchBaseQuery({ baseUrl: '/' }),
  endpoints: () => ({}), // Empty!
});

// 2. Feature file (Loaded later via React.lazy)
// We inject the new endpoints into the existing API slice
export const extendedApi = api.injectEndpoints({
  endpoints: (builder) => ({
    getSecretAdminData: builder.query({
      query: () => 'admin/secret',
    }),
  }),
});

export const { useGetSecretAdminDataQuery } = extendedApi;
